'萝月挂朝镜，松风鸣夜弦',
'昨夜梁园里，弟寒兄不知',
'天寒素手冷，夜长烛复微',
'而我谢明主，衔哀投夜郎',
'半夜水军来，浔阳满旌旃',
'辞官不受赏，翻谪夜郎天',
'夜郎万里道，西上令人老',
'抚剑夜吟啸，雄心日千里',
'夜栖寒月静，朝步落花闲',
'南湖秋月白，王宰夜相邀',
