'一夜春风入高柳，恍如身在海涛中',
'去年此夜深闺月，今向兴州山上明',
'可怜细雨轻寒夜，正是故园花发时',
'他年一枕江关梦，知忆蓬窗此夜声',
'昼思夜梦人非远，客附书来喜可知',
'夜色明光酒，春风长信裾',
