'自嫌尚有人间意，射雉归来夜读书',
'空斋夜方中，窗月淡如水',
'轻冰满研风声急，忽记山阴夜雪时',
'十年人向三巴老，一夜阳从九地来',
'恨不来为清夜饮，月中香露湿乌巾',
'忆在锦城歌吹海，七年夜雨不曾知',
'毳衲年年补，纱灯夜夜明',
'空堂无人夜向中，卧看床前烛花吐',
'梦里偶同清夜宴，醉中犹揽故人须',
'黄亭一夜风吹雨，似为游人洗俗尘',
'一夜北风吹裂屋，石楼无耳不曾闻',
'冬旱土不膏，爱此春夜雨',
'南市夜夜上元灯，西郊日日是清明',
'无端老作天涯客，还听当时夜雨声',
'天河渐近鹊桥时，一夜风吹斗柄移',
'天阔素书无雁寄，夜阑清梦有灯知',
