'夜长谁作幽人伴，惟是蛩声与月明',
'秋雨不肯晴，秋夜不肯明',
'犹应寒夜中，山月来铺练',
'密雪夜来积，起见万物春',
'青山夜来雨，溪水已潺湲',
'寒风一夜起，曩事无不思',
'一夜临流对明月，举杯愁听雁来声',
'偏知寒夜屋，不管醉归人',
'流年不贷人，白发日夜宻',
'剩欲约公风雨夜，一灯相对话平生',
'秋雨初霁开长空，夜天无云吐白虹',
'十里烟波明月夜，万人歌吹早莺天',
