'夜来月色明如昼，却向庭芜数落红',
'谁可对床听夜雨，自于同社燕春醪',
'闲作此来横笛夜，爱看人醉落帆风',
'祇为酒醒愁夜永，二虫得失我何心',
'人言可望不可亲，夜半叩门宁复听',
'驿门深闭柏参天，月可中庭夜影圆',
'山外斜阳湖外雪，夜来阴霭晓来晴',
'从此三年风雨夜，寂寥棋局与清樽',
'夜长人不寐，地僻月初生',
'后夜龙归云浪湿，未明人起月华鲜',
'夜来窗不掩，吹落一瓶花',
'常时夜雨急，随雨来枕上',
'春山寒食节，夜雨昼晴天',
'年年机杼妾，独怨夜何长',
'夜深雨过山形出，天静云空月色佳',
'夜落梅花应满路，风含春色自吹衣',
'今夜雨昏山月暗，泪痕元不减金波',
'长安深夜雪漫漫，欲觅心安转不安',
'星斗绣天长不夜，疑乘风驭扣瑶扉',
'我来拟作叔夜辈，一听空山鸾凤声',
'坐到夜深明月上，秋声故故绕梧桐',
'雨湿东风三月尾，夜寒烧烛照花睡',
'何时一青灯，夜雨同对床',
'三径无资出宦游，归心日夜绕松楸',
'雪花夜堕方如许，天宇晨开岂有他',
'闻道田家日夜愁，黄云白雪不全收',
'荒冢魂长夜，空山草自春',
'秋风一夜来消息，又却见渠先弃掷',
'离心落雁惊秋雨，醉眼开花昨夜风',
'对床夜话知他日，幽赏如何得细听',
'我方西上夜，夜夜家山侧',
'扶桑忽上东海来，一夜天清风露白',
'何人夜半诗博酒，鬼神欲泣如楚囚',
'是客胸中春百顷，日夜葩花落毛颖',
'远浦三更月，春风一夜程',
