'可怜此夜商山客，画尽炉灰泪满衣',
'晚归上马颇自适，狂吟醉舞夜不休',
'戢翼盘桓傍小庭，不无清夜梦烟汀',
'一棹寒灯随夜钓，满犁膏雨趁春耕',
'人心若江河，昼夜无停流',
