'真似吾家雪溪上，东风一夜隔篱闻',
'泽国连朝雨，春山半夜雷',
'酒阑寒食夜，月上海棠花',
'时闻清夜雪中犬，回视红尘井底蛙',
'秋风夜来急，吹落碧莲无',
'夜月锁云林，春花绣岩壑',
'禅心不动澄潭月，俗耳常惊静夜雷',
'自缘人意夸今夜，岂是蟾光胜旧时',
'且倾渌酒樽，慰此清夜梦',
'道卿诗思清如水，披衣霜夜吟寒星',
'一夜山南雪，清寒江上州',
'拙客懒同嵇叔夜，少年文爱马相如',
