'故应有德神明相，宁事祈禳叩夜坛',
'郊原脉起新春雨，帘幕寒生半夜风',
'一夜奎星向紫微，朝来黄鹄又东归',
'无端唤起江南梦，记得扁舟夜不眠',
'新秋拂水无行迹，夜夜随潮过江北',
