'清风时来助气势，寒甲夜聚言语私',
'夜梦不厌劳，百里夕一驰',
'夜以盗自来，何敢怨犬伤',
'淮风情舒舒，楚水日夜流',
'一夜风声惊屋破，四邻叩壁呼我贺',
