'夜中闻长啸，月露荒榛芜',
'笑谈惊半夜，风雨暗长檠',
'卯酒无虚日，夜棋有达晨',
'悬知冬夜长，不恨晨光迟',
'大瓢贮月归春瓮，小杓分江入夜瓶',
