'一椀镫寒听夜雨，半床毡暖卧春云',
'水声常夜雨，山气即朝云',
'秋夜不可晨，悲歌聊自永',
'江头夜雪好披去，湖上春光宜棹归',
'人间厚福终归尽，涨海难停一夜涛',
'山深瘴暖霜露干，夜长无衣犹苦寒',
