'寂寞银灯愁不寐，萧萧风竹夜窗寒',
'雨滴闲堦清夜久，焚香偏忆白云人',
'行子不须愁夜泊，绿杨多处有人烟',
'王昌家直在城东，落尽庭花昨夜风',
'月上重楼丝管秋，佳人夜唱古梁州',
'井花净洗行人耳，留听溪声入夜潮',
'进经逢乙夜，展礼值明时',
'遥夜淮弥净，浮空月正明',
'风清五夜永，节换一阳生',
'客心宜静夜，月色澹新秋',
'何朝逢暑雨，几夜泊鱼烟',
'凉风遥夜清秋半，一望金波照粉田',
'渔潭明夜泊，心忆谢玄晖',
'剑履归长夜，笳箫咽暮云',
'此夜不堪肠断绝，愿随流影到辽东',
