'一颦一笑千金重，肯似成都夜失身',
'心想洞房夜，知君还向隅',
'以兹皓月圆，不厌良夜深',
'今夜子陵滩下泊，自惭相去九牛毛',
'雨霜鸿唳天，匝树鸟鸣夜',
'翡翠无穷掩夜泉，犹疑一半作神仙',
