'方响闻时夜已深，声声敲著客愁心',
'西斋风雨夜，更有咏贫诗',
'猿声断肠夜，应向雨中闻',
'久客怨长夜，西风吹雁声',
'溪冰寒棹响，岩雪夜窗明',
'晴烟和草色，夜雨长溪痕',
'夜灯江北见，寒磬水西闻',
'夜棋留客宿，春酒劝僧倾',
'谁言今夜月，同是洛阳人',
'春桥悬酒幔，夜栅集茶樯',
'孤吟不可曙，昨夜共登楼',
'夜碁全局在，春酒半壶空',
'石燕拂云晴亦雨，江豚吹浪夜还风',
'对雪夜穷黄石略，望云秋计黑山程',
'怜君诗句犹相忆，题在空斋夜夜吟',
