'自蒙半夜传衣后，不羡王祥得佩刀',
'灞陵夜猎随田窦，不识寒郊自转蓬',
'夜夜桂露湿，村村桃水香',
'六曲连环接翠帷，高楼半夜酒醒时',
'含情春晼晚，暂见夜阑干',
'秋霖腹疾俱难遣，万里西风夜正长',
'帘开最明夜，簟卷已凉天',
'鄂君怅望舟中夜，绣被焚香独自眠',
'兔寒蟾冷桂花白，此夜姮娥应断肠',
'水仙欲上鲤鱼去，一夜芙蓉红泪多',
