'客散酒醒深夜后，更持红烛赏残花',
'甘膏滴滴是精诚，昼夜如丝一尺盈',
'滞雨长安夜，残灯独客愁',
'背灯独共余香语，不觉犹歌起夜来',
'吴馆何时熨，秦台几夜熏',
'夜卷牙旗千帐雪，朝飞羽骑一河冰',
'常娥衣薄不禁寒，蟾蜍夜艳秋河月',
'非关无烛夜，其奈落花朝',
'即时贤路辟，此夜泰阶平',
'生小太平年，不识夜闭门',
