'乔木老含春色澹，夜溪寒带月光流',
'几程烟水秋光远，半夜星河天气高',
'祗应清夜梦，时复到荒庐',
'谁言千里隔，夜夜梦吾家',
'此夜山川宜断取，为予携到若翁前',
'幽人有轩榻，日夜与之对',
'况当昼夜初停处，正是炎凉得所时',
