'欲扫空斋同夜话，山荒黄独尚无苗',
'关法晨方度，其如夜未明',
'一朝烟尘起荆益，半夜虎符来抽摘',
'春煖披香殿，夜寒长信宫',
'多谢小窗半规月，夜深长伴绛纱边',
