'夜半灵根濯清水，丹田浊气切须呵',
'冬夜那何晨，斜河耿高树',
'夜檐月送影，昼户烟输晴',
'夜灯照出千古心，晓窗掣破重玄锁',
'余霞照宝瑟，明夜欺银釭',
'窗明朝采烂，枝瘦夜光蟠',
