'黄鸡喔喔丑前催，拟效张侯夜半来',
'至今霜月夜，松竹带芳徽',
'慈庭春后寂，书幌夜深寒',
'杏园春接袂，蓬省夜分灯',
'冠盖任云浮，门前日夜流',
'风急啼乌夜，霜零断雁秋',
'群动芸芸看夜息，万生点点发春辉',
'事业古人谋，寒镫耿夜篝',
'嫠纬愁春昼，儿书课夜深',
'夜战祁连山，断甲溅腥血',
'酒催清夜别，身伴白云还',
'芭蕉漱漱连夜雨，桂子纷纷落庭户',
