'吟成亟取夜钟敲，淡月笼窗昏晓交',
'团团玉叶振天芳，清澈琼楼午夜光',
'君勇欲兼之，日夜吟辛酸',
'桐阴覆月色，静夜独往还',
'卿月高秋部，恩波彻夜郎',
'笔阵森森万马肃，夜雪未搅千群鹅',
'只有潮声似政声，日夜流传喧两耳',
'试向璇玑观大象，三台夜夜色齐同',
