'朝看贝叶牢笼佛，夜礼星辰取奉天',
'几番清夜月，孤影度南桥',
'读罢黄庭一卷经，磬残烟冷夜坛清',
'茅屋鸡声勘夜分，杖藜挑月带余醺',
'夜凉偶出庭心看，缺处光涵三两星',
'昨夜瞻奎宿，寒芒万丈明',
'试霜寒尚薄，落叶夜初长',
'空庭杳已夜，孤坐悄无言',
'又闻寇盗湖南起，不觉迟回夜半眠',
'玉兔金乌元去速，晓猿夜鹤怪归迟',
'长江秋色将征旆，半夜霜威袭客毡',
'江湖醉墨争驰骋，谁识岩灯夜夜红',
'揖坐楼头夜，酒杯生菜盘',
'想应今夜宿，霜月满瓜洲',
'向来多朋从，痛饮忘夜寐',
'蚤夜念倚门，翼翼如有临',
'夜阑更秉烛，檐雪声锵锵',
'灯花残夜半，桂子落秋深',
'莲浦秋堂晚，松冈夜室长',
'诗书早已传家学，场屋谁知负夜灯',
'景星助月夜，光入清溪湄',
'夜半军书尚掣铃，想应欹枕梦难成',
