'秋晏车箱访流马，夜深弧矢看天狼',
'秋近夜初长，开窗病骨凉',
'秋成正望狼烽急，夜枕不禁鱼目鳏',
'井蛩一夜秋已至，寸丝千结萦柔肠',
'循阶闻夜蛩，有酒仍独倾',
'奎章夜下九重天，雍乘畴咨法从贤',
'小槽滴沥竹笕承，冰渠夜溅真珠明',
'海雾夜涵润，山霞朝欲然',
'吹彻玉笙正凉透，香风万斛夜漫漫',
'红妆绿水照清夜，彩仗青旗朝大昕',
'幸有玉延炊夜月，肯令绣谷咽朝霞',
'霜澄夜气俱明彻，云澹秋容想泬寥',
'家人治尊罍，夜漏觇晨晞',
'古郡裁仪自太平，百艘初奏夜严声',
'昨夜浓云望东北，祇应雨脚在三吴',
'摇光一夕动北斗，浓霾五夜迷东望',
'浓岚晨历历，流水夜泠泠',
'五夜钟声上直时，焚香重熨早朝衣',
'六师夜撤广陵围，积甲芜城一样齐',
'雒坛爟火夜升烟，卤簿如云绣色鲜',
'黄伞登台城夜启，参旗不展泰阶平',
'昨夜清台占上瑞，乐章已奏月重轮',
'狄家天使夜行边，穆卜亲占百字钱',
'通志一编新进御，汉宫五夜剪金莲',
'午夜红光照禁中，贡金铸鼎效神工',
'金花诏纸夜封芹，首录先朝社稷臣',
'马渡朝迎敌，钟山夜驻营',
'暝色阻穷探，夜雨得佳眠',
'忆昨涪江滨，对吟夜床雨',
'幽怀无与娱，欹枕清夜游',
'棘人有余哀，揽衣良夜遒',
'夜窗讶明皎，晓槛俄纷飘',
'沉思夜继日，叹息复叹息',
'沥胆濡毫肝作纸，封章夜诉天尺咫',
'矞云昼护耀魄宝，玉绳夜低天市垣',
'临邛自昔多仙才，鹤鸣神丹夜昭回',
'物华过眼半黄凋，万窍号风夜栗憀',
'西阁夜阑犹跋烛，北岩晚霁趣归舟',
'残年准拟登牛首，连夜匆忙过马当',
'晚烟莽苍乱流去，夜雨淋浪欹枕听',
'款门心讶三医谒，藏壑舟惊半夜扛',
'翻思田舍朋簪盍，浊酒青灯语夜阑',
'笔花枉着蓝田纸，谁直金銮夜演纶',
'好在玉壶清夜里，冷香孤艳浸空明',
'侵天围棘孤吟夜，且著红炉为暖愁',
'半夜瓦沟飞急响，化工元不吝生成',
'一夜凉侵蕲竹簟，最宜欹枕听鸣蛙',
'昨夜青皇驾趣旋，星榆散漫晚风颠',
'持杯未咽思玄度，今夜微吟何处村',
