'雨余留得闲踪迹，绿染浮萍夜听蛙',
'训狐圣得知，夜半叫已屡',
'晴雷昼夜激奔湍，涧草岩花亦耐寒',
'桐柏山高空翠寒，夜深星斗近仙坛',
'思苦夜无眠，吟成托邮骑',
'病夫夜不眠，五鼓始交睫',
'归途抵温陵，除夜大促迫',
'无端野狐精，昏夜入为盗',
'暮夜光烛天，彗星大于帚',
'渥洼骥子展足长，朝发燕都夕夜郎',
'蕊珠午夜鸣玉珂，五侯门下肩相摩',
'床头金尽羞悭囊，山鬼吹灯夜恓惶',
'韩掾才情妙，吟成苦夜长',
'别久恨无书寄雁，夜深犹记案帷萤',
'共君三两夜清话，洗我千万斛奇愁',
'马肥已报高秋警，鹤唳那堪中夜闻',
'回首白云添旧感，细听夜雨入新愁',
'短鞯淋血斩将归，夜斲坚冰濡马渴',
'桐叶飘零月似冰，并河灯火夜寒生',
'衾薄疑秋老，茶多觉夜长',
'辟户夜通月，掬泉朝饮星',
'捷书夜至连清昼，不闻传箭赤白囊',
'落成灯火夜，万点天星移',
'今汝独聒聒，昼夜长喧呼',
'夜报前溪渔，命酒将鲙享',
'夜起吟芳什，凉风吹桂轮',
'三以囊封入紫微，一星今夜出郎闱',
'一夜清霜殒物华，寒芳开晚独堪嘉',
'露从今夜白，菊是去年黄',
'夜阑天际堕金盆，膝上焦桐调转新',
'呼灯隔夜书名纸，未审朱门复见谁',
'只好罢休看，夜深风露寒',
'清夜不复寐，萧然据胡床',
'登览未应迷宿昔，夜猿啼在晋时枫',
'昨夜溪上归，云下扣松扉',
'树藏春洞黑，石拥夜泉鸣',
'醉来含笑看吴钩，龙光夜半干斗牛',
