'食指怪生连夜动，敲门郭索送诗来',
'秋堂风露夜沉沉，赖有寒螀伴苦吟',
'夜阑秉烛浮大白，款接软语春怡融',
'昨夜群仙宴十洲，再三招我伴清游',
