'夜半闻洞箫，知是神游处',
'正好𬬻亭语夜分，朔风征帽浙江𣸣',
'古篆生春霭，新汤响夜潮',
'诗魂夜寄青林月，渔唱声回绿树烟',
'一榻翛然著醉侬，沉沉清夜大槐宫',
'尚约秋吟夜，江声带雨听',
'昼诵夜无灯，早寝接晏起',
'造化仁民意，潇潇夜雨声',
