'不辨昼夜分，恍疑世代更',
'缱绻谈至夜，霜月照露苔',
'夜深投寺解行装，一点寒灯照上方',
'夜呵刀尺制寒衣，儿小却倩人封题',
'见说传更增逻卒，已闻犯夜少奸民',
